+/* Format GEO position (X or Y axis) with 0.08m resolution */
+static void fmt_geo_xy_position2(char *label, int64_t c) {
+    c = c * 8;
+    if (c >= 0) {
+        snprintf(label, ITEM_LABEL_LENGTH, "%" PRId64 ".%02" PRId64 "m", c / 100, c % 100);
+    }
+    else {
+        snprintf(label, ITEM_LABEL_LENGTH, "-%" PRId64 ".%02" PRId64 "m", -c / 100, -c % 100);
+    }
+}
